// Original Session.execute oracle for animation activation/removal and sampled insertion.
use serde_json::{json,Value};use sha2::{Digest,Sha256};
use filmcraft_project::{ParamValue as V,Keyframe,Interpolation as I};use filmcraft_time::Tick;
fn hash(v:&Value)->String{format!("{:x}",Sha256::digest(serde_json::to_vec(v).unwrap()))}
fn main()->Result<(),Box<dyn std::error::Error>>{
 let mut s=filmcraft_engine::Session::default();s.execute("file.openDemoProject",json!({}))?;let sequence=s.state.active_sequence.unwrap();let base=s.project.clone();let clip=base.sequence(sequence).unwrap().video_tracks[0].items[0].id;
 let mut instances=Vec::new();let mut jobs:Vec<(usize,&str,Value,i64,Value)>=Vec::new();
 let changes=json!({"start":0,"source_in":0,"speed":1.,"reverse":false,"frame_hold":null});
 for d in filmcraft_project::effect_defs(){let mut e=d.instance();e.enabled=false;let i=instances.len();for name in e.params.keys(){for cmd in ["effects.toggleAnimation","effects.addKeyframe"]{jobs.push((i,cmd,json!({"clip":clip.0,"effect":d.id,"param":name}),40,changes.clone()));}}instances.push(e);}
 let path=filmcraft_project::mask::MaskPath::rect(0.,0.,10.,10.);let path2=filmcraft_project::mask::MaskPath::rect(2.,3.,20.,30.);
 let pairs=vec![(json!({"Float":1.}),json!({"Float":9.})),(json!({"Vec2":{"x":1.,"y":null}}),json!({"Vec2":{"x":9.,"y":8.}})),(json!({"Color":[0.1,0.2,0.3,0.4]}),json!({"Color":[0.9,0.8,0.7,0.6]})),(json!({"Bool":false}),json!({"Bool":true})),(json!({"Choice":0}),json!({"Choice":5})),(json!({"Text":"left"}),json!({"Text":"right"})),(json!({"Curve":[[0.,0.],[1.,1.]]}),json!({"Curve":[[0.,1.],[1.,0.]]})),(json!({"Path":path}),json!({"Path":path2})),(json!({"Float":1.}),json!({"Vec2":{"x":2.,"y":3.}})),(json!({"Path":path}),json!({"Path":filmcraft_project::mask::MaskPath::default()}))];
 for (left,right) in pairs {
  for a in I::ALL{for b in I::ALL{
   let mut e=filmcraft_project::find_effect("motion").unwrap().instance();e.enabled=false;let p=e.params.get_mut("scale").unwrap();p.value=V::Float(-100.);p.keyframes=vec![Keyframe::new(Tick(0),serde_json::from_value(left.clone())?),Keyframe::new(Tick(100),serde_json::from_value(right.clone())?)];p.keyframes[0].interp=a;p.keyframes[1].interp=b;p.keyframes[0].out_influence=0.93;p.keyframes[1].in_influence=0.81;
   let i=instances.len();instances.push(e);for cmd in ["effects.toggleAnimation","effects.addKeyframe"]{jobs.push((i,cmd,json!({"clip":clip.0,"param":"scale"}),40,changes.clone()));}
   if a==I::Linear&&b==I::Linear{for time in [-1,0,100,101]{for cmd in ["effects.toggleAnimation","effects.addKeyframe"]{jobs.push((i,cmd,json!({"clip":clip.0,"param":"scale"}),time,changes.clone()));}}}
  }}
 }
 // Source-time mapping includes clamping, reverse, speed and held frames; toggle ignores explicit time.
 let mut motion=filmcraft_project::find_effect("motion").unwrap().instance();motion.params.get_mut("scale").unwrap().keyframes=vec![Keyframe::new(Tick(0),V::Float(10.)),Keyframe::new(Tick(100),V::Float(90.))];let mi=instances.len();instances.push(motion.clone());
 for(speed,reverse,held,filters)in [(2.,false,None,false),(2.,true,None,false),(2.,true,Some(60),false),(2.,true,Some(60),true),(0.,false,None,false),(-2.,false,None,false)]{for cmd in ["effects.toggleAnimation","effects.addKeyframe"]{jobs.push((mi,cmd,json!({"clip":clip.0,"param":"scale","time":75}),20,json!({"start":0,"duration":200,"source_in":0,"speed":speed,"reverse":reverse,"frame_hold":held,"hold_filters":filters})));}}
 // One-key removal and all effect-mask parameter targets.
 motion.params.get_mut("scale").unwrap().keyframes.remove(0);let one=instances.len();instances.push(motion);for cmd in ["effects.toggleAnimation","effects.addKeyframe"]{jobs.push((one,cmd,json!({"clip":clip.0,"param":"scale"}),100,changes.clone()));}
 let mut opacity=filmcraft_project::find_effect("opacity").unwrap().instance();let mut mask=filmcraft_project::mask::Mask::new("Test",path.clone());for name in ["path","feather","opacity","expansion"]{let p=mask.param_mut(name).unwrap();p.keyframes=vec![Keyframe::new(Tick(0),p.value.clone()),Keyframe::new(Tick(100),p.value.clone())];}opacity.masks.push(mask);let maski=instances.len();instances.push(opacity);for name in ["path","feather","opacity","expansion"]{for cmd in ["effects.toggleAnimation","effects.addKeyframe"]{jobs.push((maski,cmd,json!({"clip":clip.0,"effect":"opacity","param":name,"mask":0}),40,changes.clone()));}}
 for cmd in ["effects.toggleAnimation","effects.addKeyframe"]{for params in [json!({"clip":clip.0,"effect":"missing","param":"scale"}),json!({"clip":clip.0,"param":"missing"}),json!({"clip":clip.0,"param":"scale","mask":99})]{jobs.push((mi,cmd,params,40,changes.clone()));}}
 let mut cases=Vec::new();for(instance,command,params,playhead,changes)in jobs{
  s.project=base.clone();s.history.undo.clear();s.history.redo.clear();s.history.merge_key=None;s.state.playheads.insert(sequence,Tick(playhead));let item=&mut std::sync::Arc::make_mut(&mut s.project).sequence_mut(sequence).unwrap().video_tracks[0].items[0];let mut raw=serde_json::to_value(&*item)?;for(k,v)in changes.as_object().unwrap(){raw[k]=v.clone();}*item=serde_json::from_value(raw)?;item.effects=vec![instances[instance].clone()];let actual=serde_json::to_value(&*item)?;let mut canonical=serde_json::Map::new();let mut removals=Vec::new();for k in changes.as_object().unwrap().keys(){if let Some(v)=actual.get(k){canonical.insert(k.clone(),v.clone());}else{removals.push(k.clone());}}
  let result=s.execute(command,params.clone());cases.push(json!({"instance":instance,"command":command,"params":params,"playhead":playhead,"clipChanges":canonical,"clipRemovals":removals,"ok":result.is_ok(),"projectSha256":hash(&serde_json::to_value(s.project.as_ref())?)}));
 }
 let header=json!({"sourceCommit":"5231852443363f001c3f6b396dd9b1e6461ae2be","sequence":sequence.0,"clip":clip.0,"project":serde_json::to_value(base.as_ref())?});let mut text=serde_json::to_string(&header)?;text.pop();text.push_str(",\"instances\":[\n");for(i,v)in instances.iter().enumerate(){if i>0{text.push_str(",\n");}text.push_str(&serde_json::to_string(&serde_json::to_value(v)?)?);}text.push_str("\n],\"cases\":[\n");for(i,v)in cases.iter().enumerate(){if i>0{text.push_str(",\n");}text.push_str(&serde_json::to_string(v)?);}text.push_str("\n]}\n");std::fs::write(std::env::args().nth(1).ok_or("output required")?,text)?;Ok(())
}
